import { MAX_BRAND_GLOW_ALPHA } from '../constants.js';
import { toRgba } from '../inputs/theme.js';
const BRAND_GLOW = {
    classic: {
        light: {
            angle: 200,
            stops: [
                [0.3, 0],
                [0.14, 35],
                [0, 85],
            ],
        },
        dark: {
            angle: 192,
            stops: [
                [0.48, 0],
                [0.16, 35],
                [0, 85],
            ],
        },
    },
    headline: {
        light: {
            angle: 351,
            stops: [
                [0.3, 0],
                [0.15, 35],
                [0, 85],
            ],
        },
        dark: {
            angle: 350,
            stops: [
                [0.5, 0],
                [0.17, 35],
                [0, 85],
            ],
        },
    },
    minimal: {
        light: {
            angle: 357,
            stops: [
                [MAX_BRAND_GLOW_ALPHA.light, 0],
                [0.16, 35],
                [0, 85],
            ],
        },
        dark: {
            angle: 352,
            stops: [
                [MAX_BRAND_GLOW_ALPHA.dark, 0],
                [0.17, 35],
                [0, 85],
            ],
        },
    },
};
export const getBrandGlow = (preset, palette) => {
    if (!palette.glow)
        return null;
    return Object.assign({ color: palette.glow.color }, BRAND_GLOW[preset][palette.glow.appearance]);
};
export const getBrandGlowCss = (glow) => {
    if (!glow)
        return undefined;
    const stops = glow.stops.map(([alpha, position]) => `${toRgba(glow.color, alpha)} ${position}%`);
    return `linear-gradient(${glow.angle}deg, ${stops.join(', ')})`;
};
